def next_smallest_palindrome(num, _n=None):
    s = str(num + 1)  # start searching strictly greater than num
    length = len(s)

    while True:
        if s == s[::-1]:
            return int(s)
        # Generate palindrome by mirroring left half to right half
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[:-1][::-1]

        if int(pal) >= int(s):
            s = pal
        else:
            # increment the left half and form palindrome again
            left_num = int(left) + 1
            left = str(left_num)
            if len(left) > half:
                # length increases, e.g. 999 -> 1000
                length += 1
                s = '1' + ('0' * (length - 1))
                continue
            if length % 2 == 0:
                s = left + left[::-1]
            else:
                s = left + left[:-1][::-1]

