def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift == 0:
        return s
    if abs(shift) > n:
        return s[::-1]
    # positive shift means circular shift to the right by shift
    shift %= n
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

