def parse_nested_parens(paren_string: str) -> List[int]:
    # The input is a string representing multiple groups of nested parentheses separated by spaces.
    # For each group, output the maximum depth of nesting.
    # If there are no spaces, assume the string consists of concatenated groups of balanced parentheses,
    # so we split them by detecting balanced groups.
    groups = []
    depth = 0
    max_depth = 0
    start = 0
    balance = 0

    # If input contains spaces, split by spaces directly
    if ' ' in paren_string:
        groups = paren_string.split()
    else:
        # No spaces, so split into balanced groups
        groups = []
        for i, ch in enumerate(paren_string):
            if ch == '(':
                balance += 1
            elif ch == ')':
                balance -= 1
            if balance == 0:
                groups.append(paren_string[start:i+1])
                start = i + 1

    result = []
    for group in groups:
        depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
        result.append(max_depth)
    return result

